    ["I had not expected you to return."] = "No esperaba que volvieras.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.Your time has come again, &lt;name&gt;."] = "Pero te has mostrado un soldado valiente y honorable de los Lobos Gélidos. Tu hora ha vuelto, <name>.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature.Present your insignia."] = "Te has ganado un nuevo rango y, con él, una nueva insignia que marca ese ascenso. Presenta tu insignia.",
    ["ProgressThe base buzzes with news of your exploits in the Field of Strife!"] = "¡La base bulle con noticias de tus hazañas en Field of Strife!",
    ["You have struck mighty blows against our enemy - crushing their morale!"] = "Has asestado golpes terribles a nuestro enemigo, ¡aplastando su moral!",
    ["For this, you have earned a rank of honor among the Stormpike.Present your insignia."] = "Por ello te has ganado un rango de honor entre los de Pico Tormenta. Presenta tu insignia.",
    ["Alliance only."] = "Solo Alianza.",
    ["Accept this talisman, &lt;class&gt;."] = "Acepta este talismán, <class>.",
    ["Accept it and use its power to strike down our mutual enemies.Know that around your neck you carry a piece of history."] = "Acéptalo y usa su poder para abatir a nuestros enemigos comunes. Sabe que llevas al cuello un pedazo de historia.",
    ["Kezan was once a grand territory of the Zandalar Empire."] = "Kezan fue antaño un gran territorio del imperio Zandalar.",
    ["Alas, the taint of goblin trade princes would force out my proud brothers and sisters.Kezan is now home to the goblin capital of the Undermine; but know that before the taint, it held greatness."] = "Pero la mancha de los príncipes mercantes goblin expulsó a mis orgullosos hermanos y hermanas. Kezan es hoy el hogar de la capital goblin, Undermine; pero sabe que, antes de la mancha, tuvo grandeza.",
    ["Still to this day Kezan is considered sacred land to my people."] = "A día de hoy, Kezan sigue siendo tierra sagrada para mi pueblo.",
    ["ProgressCall forth your demons, &lt;class&gt;."] = "Invoca a tus demonios, <class>.",
    ["Let them bask in the energy of Kezan's Taint."] = "Deja que se empapen de la energía de la Mancha de Kezan.",
    ["Command them on the field of battle!"] = "¡Mándalos al campo de batalla!",
    ["Decimate the enemy!Yes..."] = "¡Diezma al enemigo! Sí...",
    ["The time has come to apply the final enhancement to Kezan's Taint."] = "Ha llegado el momento de aplicar la mejora final a la Mancha de Kezan.",
    ["Give me the talisman."] = "Dame el talismán.",
    ["Here's your armor, &lt;name&gt;. &nbsp;Furen's process worked brilliantly! &nbsp;Perfectly! &nbsp;Marvelously, truly!You could run this armor over with a siege engine and it would spring right back into shape!"] = "Aquí tienes la armadura, <name>. &nbsp;¡El proceso de Furen funcionó de maravilla! &nbsp;¡Perfecto! &nbsp;¡Maravilloso, de verdad! Podrías pasar una máquina de asedio por encima y volvería a su forma al instante.",
    ["ProgressBefore me stands an exalted hero of the Alliance.&lt;Lieutenant Haggerdin salutes.&gt;Few have earned such a rank among the Stormpike."] = "Ante mí se alza un héroe exaltado de la Alianza. <El teniente Haggerdin saluda.> Pocos han ganado tal rango entre los de Pico Tormenta.",
    ["I have watched the enemy fall before you."] = "He visto caer al enemigo ante ti.",
    ["I have seen their resolve crumble in your presence."] = "He visto su resolución desmoronarse en tu presencia.",
    ["When you enter the fray, you become the beacon of hope for our forces!Present your insignia."] = "Cuando entras en la refriega, te conviertes en el faro de esperanza de nuestras fuerzas. ¡Presenta tu insignia!",
    ["ProgressAn extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock. &nbsp;The front of the cabinet is deeply scratched and marked. &nbsp;This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.If you are going to open this cabinet, you will need to find the key."] = "Ante ti se alza un armario extremadamente sólido, bien cerrado con una cerradura integrada. &nbsp;El frente está profundamente rayado y marcado. &nbsp;Cabe suponer que son los restos de numerosos intentos violentos y fallidos de revelar los secretos que el armario oculta. Si vas a abrir este armario, tendrás que encontrar la llave.",
    ["ProgressMolthor delivers word from King Rastakhan, &lt;name&gt;."] = "Molthor trae palabra del rey Rastakhan, <name>.",
    ["The royal court is most impressed with your decimation of the Hakkari forces."] = "La corte real está muy impresionada por cómo has diezmado a las fuerzas Hakkari.",
    ["I am to award you with the final weave in your talisman."] = "Debo concederte el tejido final de tu talismán.",
    ["Hand it to me."] = "Dámelo.",
    ["Rituals of Power sends you into Scarlet Monastery Library."] = "«Rituales de poder» te envía a la biblioteca del Monasterio Escarlata.",
    ["Bring Bink her Mage-tastic Gizmonitor."] = "Llévale a Bink su Trastónitor maguitronic.",
    ["Here is your robe. &nbsp;It's one of my best made yet! &nbsp;Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!"] = "Aquí tienes la toga. &nbsp;¡Es de las mejores que he hecho! &nbsp;Llévala con orgullo y, cuando pregunten... di que la conseguiste en Larson Clothiers.",
    ["I have finished with your piece of armor, and I am quite pleased. &nbsp;Furen's new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.Thank you, &lt;name&gt;. &nbsp;And may this serve you well in future battles."] = "He terminado tu pieza de armadura, y estoy muy satisfecho. &nbsp;Las nuevas técnicas de Furen encajaron a la perfección con las mías, y estoy seguro de que esta armadura será muy resistente. Gracias, <name>. &nbsp;Que te sirva bien en las batallas que vienen.",
    ["&lt;name&gt;, your successful re-engineering of the cauldrons is a tremendous victory for us!Let all within my presence hear: for service to the Forsaken and to the Horde as a whole above and beyond what was expected - in the face of overwhelming odds and incredible danger, might I add - I give &lt;name&gt; this, and I extend upon him our undying gratitude as a true hero of the Horde. &nbsp;Huzzah!"] = "<name>, tu reingeniería de los calderos es una victoria enorme para nosotros. Que lo oigan todos los presentes: por un servicio a los Renegados y a toda la Horda muy por encima de lo esperado, frente a una superioridad aplastante y un peligro increíble, añadiría, entrego esto a <name> y le expreso nuestra gratitud eterna como verdadero héroe de la Horda. &nbsp;¡Hurra!",
    ["Here is your nether-lace, &lt;name&gt;. &nbsp;It is both comfortable and durable, and holds the magic of the laughing sisters' hair.Enjoy, and if you find it amenable, please mention so to Deino. &nbsp;She is a &lt;class&gt; on whose good side I wish to stay..."] = "Aquí tienes tu encaje abisal, <name>. &nbsp;Es cómodo y resistente, y guarda la magia del pelo de las hermanas risueñas. Disfrútalo y, si te gusta, díselo a Deino. &nbsp;Es una <class> a cuya buena sombra quiero seguir...",
    ["Now isn't this interesting?"] = "¿No es interesante?",
    ["You say you found this tablet on a small, deserted island at The Overlook Cliffs in The Hinterlands, &lt;class&gt;?"] = "¿Dices que encontraste esta tablilla en una islita desierta de The Overlook Cliffs, en las Tierras del Interior, <class>?",
    ["Very interesting indeed."] = "Muy interesante, desde luego.",
    ["I thank you for your efforts in this matter."] = "Te agradezco el esfuerzo en este asunto.",
    ["Our Dark Lady shall be very pleased with this discovery."] = "Nuestra Dama Oscura estará muy complacida con este descubrimiento.",
    ["Here, allow me to reward you proportionately."] = "Toma, permite que te recompense en proporción.",
    ["Erlgadin in Stranglethorn Vale."] = "Erlgadin, en la Vega de Tuercespina.",
    ["Progress*Whir* *Click* &nbsp;I seek rare fish for Fishmaster Bluegill to catalogue. &nbsp; If you bring me a Keefer's Angelfish, I will provide you with this fine reward. *Zzzap* *Whir*."] = "*Brrr* *Clic* &nbsp;Busco peces raros para que Fishmaster Bluegill los catalogue. &nbsp; Si me traes un Pez ángel de Keefer, te daré esta bella recompensa. *Bzzz* *Brrr*.",
    ["Find what awaits you."] = "Descubre lo que te espera.",
    ["It will take time for our scholars to study the pendant you brought us. &nbsp;But for your service to the Horde I would like to offer you a small token.Thank you, &lt;name&gt;. &nbsp;Your acts bring honor to you, and to us."] = "Nuestros eruditos tardarán en estudiar el colgante que nos trajiste. &nbsp;Pero por tu servicio a la Horda quiero ofrecerte una pequeña muestra. Gracias, <name>. &nbsp;Tus actos te honran, y nos honran a nosotros.",
    ["Return the monogrammed silver hair clip to its owner."] = "Devuelve la horquilla de plata con monograma a su dueña.",
    ["Here are your robes, &lt;name&gt;. &nbsp;Wear them well."] = "Aquí tienes las togas, <name>. &nbsp;Llévalas bien.",
    ["ProgressIt is good to see you in good health, &lt;name&gt;."] = "Me alegra verte con buena salud, <name>.",
    ["The glorious battles you have undertaken affect all life on this planet."] = "Las gloriosas batallas que has librado afectan a toda vida en este mundo.",
    ["Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.Give me your talisman and I shall amplify its strength."] = "Hakkar nunca debe salir de Zul'Gurub, o el mundo se hundirá bajo su hambre inmensa. Dame tu talismán y amplificaré su fuerza.",
    ["Use the Strength of Mugamba to punish our enemies!"] = "¡Usa la Fuerza de Mugamba para castigar a nuestros enemigos!",
    ["ProgressDrek'Thar sings your praises."] = "Drek'Thar canta tus alabanzas.",
    ["Kalimdor is abuzz with tales of your heroics."] = "Kalimdor bulle con relatos de tus heroicidades.",
    ["The Warchief glows - your stalwart defense of our clan has pleased him greatly.You have earned the Eye of Command.Present your insignia, Commander &lt;name&gt;."] = "El Jefe de Guerra resplandece: tu defensa firme de nuestro clan le ha complacido mucho. Te has ganado el Ojo de Mando. Presenta tu insignia, comandante <name>.",
    ["ProgressTales of your battles against the Gurubashi are whispered in the winds, &lt;class&gt;."] = "Los relatos de tus batallas contra los Gurubashi se susurran en el viento, <class>.",
    ["Even royalty is beginning to talk of your deeds."] = "Hasta la realeza empieza a hablar de tus hazañas.",
    ["It is rumored that King Rastakhan even mentioned you by name.The time has come to imbue the Eye."] = "Se rumorea que el rey Rastakhan llegó a decir tu nombre. Ha llegado el momento de imbuir el Ojo.",
    ["Hand me the talisman and I shall perform the service."] = "Dame el talismán y realizaré el servicio.",
    ["ProgressNever have I seen such tenacity!"] = "¡Nunca he visto tal tenacidad!",
    ["The Bronze Flight grants you one final enchantment."] = "El Vuelo Bronce te concede un último encantamiento.",
    ["The Timeless One himself has requested it so!Hand me your signet ring so that I may make the necessary adjustments."] = "¡El Atemporal en persona lo ha pedido! Dame tu anillo de sello para que haga los ajustes necesarios.",
    ["Know this, heathen: A catastrophe has brought us together."] = "Sabe esto, pagano: una catástrofe nos ha reunido.",
    ["Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people."] = "Tus costumbres paganas ni se entienden ni se aprecian en Zandalar, pero somos un pueblo justo.",
    ["Wear this brand around your neck."] = "Lleva esta marca al cuello.",
    ["It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.Continue to serve our people and I will amplify the power of the brand."] = "Servirá de aviso a nuestros enemigos y de símbolo de tu amistad con Zandalar. Sigue sirviendo a nuestro pueblo y amplificaré el poder de la marca.",
    ["&lt;name&gt;, you have slain all three beasts that comprise the Ashenvale Hunt. &nbsp;You have brought me adequate proof of their demise; there is no question of your strength and tenacity. &nbsp;The blood of a hunter streaks through your veins, and you should be commended!Please, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today. &nbsp;May your ancestors watch over you!"] = "<name>, has matado a las tres bestias de la Caza de Vallefresno. &nbsp;Me has traído pruebas suficientes de su fin; tu fuerza y tu tenacidad no se discuten. &nbsp;La sangre de un cazador corre por tus venas, y mereces elogio. Por favor, acepta esta baratija como felicitación por las grandes hazañas hechas hoy en Vallefresno por la Horda. &nbsp;¡Que tus antepasados velen por ti!",
    ["ProgressAh, &lt;name&gt;, it is good to smell you again.You'll have to excuse my sense of humor."] = "Ah, <name>, qué gusto volver a olerte. Tendrás que disculpar mi sentido del humor.",
    ["It can be most foul at times.I sense that you have caused great anguish to our enemies."] = "A veces puede ser de lo más fétido. Percibo que has causado una gran angustia a nuestros enemigos.",
    ["The forces of Hakkar cry out your name in anger."] = "Las fuerzas de Hakkar gritan tu nombre con ira.",
    ["This is most excellent.You have earned another weave on your talisman."] = "Esto es excelente. Te has ganado otro tejido en tu talismán.",
    ["ProgressKing Rastakhan sends his regards, Master &lt;name&gt;."] = "El rey Rastakhan envía sus saludos, maestro <name>.",
    ["Such an honor has never been given to one outside the Zandalar tribe.Give me your talisman so that I may enhance it once more."] = "Tal honor nunca se había dado a alguien de fuera de la tribu Zandalar. Dame tu talismán para mejorarlo una vez más.",
    ["Know that the Rage of Mugamba is now intrinsically connected to your very soul."] = "Sabe que la Ira de Mugamba está ahora unida a tu propia alma.",
    ["Greetings, champion."] = "Saludos, campeón.",
    ["I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.I have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove."] = "Soy Jonathan, guardián del gong sagrado y vigilante eterno del Vuelo Bronce. El Atemporal en persona me ha facultado para concederte un objeto a tu elección de su tesoro intemporal.",
    ["May it aid you in your battles against C'Thun."] = "Que te ayude en tus batallas contra C'Thun.",
    ["Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines."] = "Ayuda a Walton a sobrevivir al encuentro con Terry Tragolargo y los marines de Kul Tiras.",
    ["Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him."] = "El mortacechador Masoj necesita que coloques los tres frascos de boticario en cumbres de las Laderas de Trabalomas y vuelvas con él.",
    ["ProgressSha-mon!"] = "¡Sha-mon!",
    ["Maywiki make a joke!&lt;Maywiki laughs.&gt;So, you been using the spirits and elements against our enemies in Zul'Gurub, eh?"] = "¡Maywiki hace un chiste! <Maywiki se ríe.> Así que has usado los espíritus y los elementos contra nuestros enemigos de Zul'Gurub, ¿eh?",
    ["Spirits be praised!Maywiki gonna brighten your orb."] = "¡Alabados los espíritus! Maywiki va a darle brillo a tu orbe.",
    ["Give it here, &lt;name&gt;."] = "Dámelo, <name>.",
    ["Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post."] = "Mata a Arnak Tótem Siniestro y lleva la prueba de tu hazaña al vigiarrisco Cuernolargo, en el Puesto Viento Libre.",
    ["Reward from the quest 'Wanted!"] = "Recompensa de la misión «Wanted!",
    ["Marez Cowl'."] = "Marez Cowl».",
    ["Otto and Falconcrest'."] = "Otto and Falconcrest».",
    ["&lt;name&gt;, I have crafted these weapons with the elunite you brought to me. &nbsp;Please, take whichever most suits you.And I must thank you. &nbsp;Working with elunite is both an honor and a pleasure."] = "<name>, he forjado estas armas con la elunita que me trajiste. &nbsp;Por favor, toma la que mejor te venga. Y debo darte las gracias. &nbsp;Trabajar la elunita es un honor y un placer.",
    ["I have the whirlwind heart, and am ready to place it within your vessel of choice.Choose your weapon, &lt;name&gt;, and know that its power is the power of Cyclonian."] = "Tengo el corazón de torbellino y estoy listo para colocarlo en el receptáculo que elijas. Elige tu arma, <name>, y sabe que su poder es el poder de Ciclonio.",
    ["ProgressIt yearns to grow, &lt;name&gt;."] = "Anhela crecer, <name>.",
    ["The talisman has soaked in all that you have done."] = "El talismán ha empapado todo lo que has hecho.",
    ["The thousands of troll corpses littering Zul'Gurub have fueled its power."] = "Los miles de cadáveres de trol que cubren Zul'Gurub han alimentado su poder.",
    ["Hand it to me and I shall make the final enhancement."] = "Dámelo y haré la mejora final.",
    ["ProgressImpressive, &lt;name&gt;."] = "Impresionante, <name>.",
    ["You have a gift for killing that I have not sensed in another in many years."] = "Tienes un don para matar que no había sentido en nadie en muchos años.",
    ["Even Molthor is aware of the work that you have done for Zandalar."] = "Hasta Molthor sabe del trabajo que has hecho por Zandalar.",
    ["It is time to enhance your talisman further."] = "Es hora de mejorar aún más tu talismán.",
    ["Give it to me."] = "Dámelo.",
    ["A Gnomeregan oddity whose Use effect grants a huge burst of attack speed."] = "Una rareza de Gnomeregan cuyo efecto de Uso otorga una enorme ráfaga de velocidad de ataque.",
    ["Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision."] = "Los druidas Feral lo guardaban solo por eso, porque funciona en forma felina, y tiene cargas limitadas, así que cada uso es una decisión.",
    ["A Nightmare-corrupted green dragon who splits himself into shades rather than face a fight whole."] = "Un dragón verde corrompido por la Pesadilla, que se divide en sombras en vez de afrontar el combate entero.",
    ["A blue dragon slain in Northrend and raised as a frost wyrm."] = "Un dragón azul matado en Rasganorte y alzado como vermis de escarcha.",
    ["He guards the final approach to Kel'Thuzad's chamber."] = "Guarda el último tramo hasta la cámara de Kel'Thuzad.",
    ["A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate."] = "Se ha puesto precio a la cabeza de Marez Cowl, consejera de alto rango y agente del Sindicato.",
    ["She was last seen within the Syndicate controlled territory of Stromgarde."] = "Se la vio por última vez en el territorio de Stromgarde controlado por el Sindicato.",
    ["A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."] = "Un can del Núcleo del fuego profundo, guardado como bestia de guardia y alimentado por los tenientes de Ragnaros.",
    ["A crafted helm that outlived several tiers of raid gear."] = "Un yelmo fabricado que sobrevivió a varios niveles de equipo de banda.",
    ["Its plans were the thing guilds actually fought over."] = "Los planos eran lo que las hermandades se disputaban de verdad.",
    ["A crypt lord of Azjol-Nerub who took Arthas's side."] = "Un señor de las criptas de Azjol-Nerub que se puso del lado de Arthas.",
    ["He holds the Arachnid Quarter's outermost hall."] = "Tiene la sala más exterior del Barrio de los Arácnidos.",
    ["A death knight who trains the Scourge's new officers."] = "Un caballero de la Muerte que entrena a los nuevos oficiales de la Plaga.",
    ["He is too strong for his own students to touch, which is exactly the point of the lesson."] = "Es demasiado fuerte para que sus propios alumnos lo toquen, y ese es justo el sentido de la lección.",
    ["A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."] = "Un horror fúngico criado en las cubas de esporas del Barrio de la Peste: menos una criatura que una cosecha que se descontroló.",
    ["A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs."] = "Una araña gigante tejida en las profundidades del Barrio de los Arácnidos, alimentada con lo que la Plaga ya no necesita.",
    ["A green dragon of Ysera's flight, turned by the Nightmare and hunted across Feralas ever since."] = "Un dragón verde del vuelo de Ysera, vuelto por la Pesadilla y cazado por todo Feralas desde entonces.",
    ["A hound handler of Ragnaros's court, who curses healing shut before the fighting starts."] = "Un cuidador de canes de la corte de Ragnaros, que cierra la sanación con una maldición antes de que empiece el combate.",
    ["A human lord who traded his life for undeath and became a lich in Scholomance."] = "Un señor humano que cambió su vida por la no-muerte y se convirtió en un exánime en Scholomance.",
    ["Killing him takes a blade specifically made to sever the bargain."] = "Matarlo exige una hoja hecha a propósito para romper el pacto.",
    ["A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."] = "Un teniente de Ragnaros que combate rodeado de sus Jurafuego y se vuelve más fuerte cada vez que uno de ellos cae.",
    ["A living mass of qiraji poison."] = "Una masa viva de veneno qiraji.",
    ["It has to be frozen solid and then shattered, which is not how most things die."] = "Hay que congelarla del todo y luego hacerla añicos, que no es como mueren la mayoría de las cosas.",
    ["A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."] = "Un nigromante del Barrio de la Peste, ascendido por su habilidad para levantar lo que acababa de matar.",
    ["A pit lord left behind when the Legion's invasion collapsed, still holding the Tainted Scar where the Dark Portal's blast burned the land."] = "Un señor del foso dejado atrás cuando la invasión de la Legión se hundió, que aún tiene la Cicatriz Impura, donde la explosión del Portal Oscuro quemó la tierra.",
    ["A plain plate glove that became famous for its random enchants -- the of Strength roll is a 7.9% chance and was worth chasing over guaranteed epics for years."] = "Un simple guante de placas que se hizo famoso por sus encantamientos aleatorios: la tirada «de fuerza» tiene un 7,9% de probabilidad y durante años valió la pena perseguirla por encima de épicos garantizados.",
    ["A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."] = "Una princesa de los elementales de tierra, y la razón de que Maraudon esté envenenado: guarda en su corazón el cuerpo de Zaetar, su consorte semidiós.",
    ["A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."] = "Una matriarca de cría qiraji cuyo veneno es tan potente que el combate es en realidad una carrera contra su ponzoña.",
    ["A red dragon of Alexstrasza's flight, broken by Nefarian's experiments."] = "Un dragón rojo del vuelo de Alexstrasza, quebrado por los experimentos de Nefarian.",
    ["He asks to be killed before the corruption finishes taking him, and apologises while he fights."] = "Pide que lo maten antes de que la corrupción termine de llevárselo, y se disculpa mientras combate.",
    ["A sandworm grown enormous under the desert, surfacing only to feed."] = "Un gusano de arena crecido hasta lo enorme bajo el desierto, que solo sale a la superficie para comer.",
    ["A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."] = "Un can cosido mantenido medio muerto de hambre a propósito, para que se comiera cualquier cosa que le enviara el Barrio de los Ensamblajes.",
    ["A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."] = "Un gigante de piedra puesto al servicio de los qiraji, que drena el maná de todos los que lo combaten y se vuelve roca cuando está lleno.",
    ["A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."] = "Un enorme excavador qiraji que engendra a sus crías en pleno combate y lanza a los intrusos contra los muros.",
    ["A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."] = "Una adoradora de Kel'Thuzad que se llevó a sus seguidores con ella a la no-muerte, y aún los manda.",
    ["An Old God, buried under Ahn'Qiraj by the titans rather than killed."] = "Un Dios Antiguo, enterrado bajo Ahn'Qiraj por los titanes en vez de ser matado.",
    ["It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."] = "Susurra a los qiraji desde entonces, y toda la guerra existe porque nunca paró.",
    ["An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."] = "Una abominación cosida con los restos de la Plaga, hecha solo para la fuerza bruta.",
    ["Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."] = "El archimago Arugal llamó a los huargen al Bosque de Argénteos para defenderse de la Plaga, perdió el control de ellos al instante y enloqueció en el Castillo de Colmillo Oscuro entre lo que había invocado.",
    ["Arugal's own belt."] = "El propio cinturón de Arugal.",
    ["He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."] = "Invocó a los huargen para salvar el Bosque de Argénteos y luego perdió la razón en el Castillo de Colmillo Oscuro, rodeado de lo que había llamado.",
    ["Avast Lubber!"] = "¡Ah del barco, novato!",
    ["Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!"] = "¡Tráeme 12 abalorios del maestro de la arena y serás gran maestro de la Arena Gurubashi!",
    ["C'Thun's mouthpiece."] = "La voz de C'Thun.",
    ["Everything the qiraji believe, they believe because he told them the Old God said it."] = "Todo lo que creen los qiraji, lo creen porque él les dijo que el Dios Antiguo lo había dicho.",
    ["Cut from the fang of one of Nefarian's drakes."] = "Tallado del colmillo de uno de los dracos de Nefarian.",
    ["Tanks wore it for the stun it shrugs off, not the numbers on it."] = "Los tanques lo llevaban por el aturdimiento que anula, no por los números.",
    ["Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five."] = "El hijo de Alamuerte, que trabaja bajo la Montaña Roca Negra para criar el vuelo cromático: dragones con la sangre de los cinco.",
    ["He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."] = "Pasó años en la corte de Ventormenta como lord Víctor Nefarius mientras el trabajo seguía.",
    ["Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."] = "Ghamoo-ra es la tortuga antigua que los naga guardan en las Cavernas de Brazanegra: tan vieja que los cultores del Crepúsculo de allí la tratan como parte del templo.",
    ["Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose."] = "El principal aojador de Hakkar, que combate atando pedazos del espíritu de sus enemigos y soltándolos.",
    ["He has overpowered all attempts at his capture."] = "Ha superado todos los intentos de capturarlo.",
    ["The Stormwind Army has placed a generous bounty on the Gnoll."] = "El ejército de Ventormenta ha puesto una generosa recompensa por el gnoll.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf."] = "Pero te has mostrado un soldado valiente y honorable de los Lobos Gélidos.",
    ["Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."] = "Guardián de los talleres de la peste de Naxxramas y del pasillo de erupciones que ha matado a más asaltantes que él.",
    ["Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."] = "El mejor resultado de Nefarian: un horror cromático de dos cabezas que lleva a la vez el aliento de cada vuelo dracónico.",
    ["Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly."] = "Antaño archimago del Kirin Tor, dejó Dalaran para fundar el Culto de los Malditos y sirvió a Ner'zhul por voluntad propia.",
    ["Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."] = "Muerto en Andorhal y alzado como exánime, gobierna Naxxramas desde un filacteria en su corazón.",
    ["One of Hakkar's high priests, who returns to his feet twice before he stays down."] = "Uno de los sumos sacerdotes de Hakkar, que se levanta dos veces antes de quedarse en el suelo.",
    ["One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."] = "Uno de los tres dracos guardianes de Nefarian, que tiene las pasarelas suspendidas sobre el suelo de la guarida.",
    ["One of Ysera's four green consorts, corrupted by the Emerald Nightmare and now roaming Feralas, rotting the ground it stands on."] = "Uno de los cuatro consortes verdes de Ysera, corrompido por la Pesadilla Esmeralda y que ahora vaga por Feralas pudriendo el suelo que pisa.",
    ["One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."] = "Uno de los tres consejeros qiraji que combaten como uno: mata a cualquiera y los supervivientes se vuelven más fuertes.",
    ["One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."] = "Uno de los tres dracos que guardan la guarida interior de Nefarian, el que se cura con las heridas que inflige.",
    ["One of three weapons from the same solitary warrior trial."] = "Una de las tres armas de la misma prueba solitaria de guerrero.",
    ["Choosing it means giving up the axe and the staff for good."] = "Elegirla significa renunciar para siempre al hacha y al bastón.",
    ["Ragnaros wielded this hammer as the Firelord."] = "Ragnaros empuñó este martillo como Señor del Fuego.",
    ["Reforging it means taking the Eye of Sulfuras from Ragnaros himself and setting it into the Sulfuron Hammer."] = "Reforjarlo significa quitarle el Ojo de Sulfuras al propio Ragnaros y engarzarlo en el Martillo de Sulfuron.",
    ["Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."] = "El colega de Razuvious en el Barrio Militar, que combate detrás de sus propios muertos y no deja de enviarlos al frente.",
    ["Revelosh was a Shadowforge explorer who went into Uldaman looking for the origin of the dwarves, and became part of the ruin instead."] = "Revelosh era un explorador de Forjatiniebla que entró en Uldaman buscando el origen de los enanos y acabó siendo parte de la ruina.",
    ["Rise and be honored!"] = "¡Levántate y recibe el honor!",
    ["Present your insignia."] = "Presenta tu insignia.",
    ["Serra'kis is the great water beast the naga breed in the flooded halls of Blackfathom Deeps, and the reason the lower temple is under water at all."] = "Serra'kis es la gran bestia de agua que los naga crían en las salas inundadas de las Cavernas de Brazanegra, y la razón de que el templo inferior esté bajo el agua.",
    ["Son of Blackhand and the last warchief of the Dark Horde, still holding Blackrock Spire long after the rest of the Horde moved on."] = "Hijo de Puño Negro y último jefe de guerra de la Horda Oscura, que aún tiene la Cumbre de Roca Negra mucho después de que el resto de la Horda siguiera adelante.",
    ["Teebu's blade sets things on fire for reasons no one has ever explained."] = "La hoja de Teebu prende fuego a las cosas por razones que nadie ha explicado jamás.",
    ["It is famous for being almost useless and deeply desirable at the same time."] = "Es famosa por ser casi inútil y muy deseable a la vez.",
    ["The Druids of the Fang broke from Cenarius and let the Emerald Nightmare into the Wailing Caverns."] = "Los druidas del Colmillo rompieron con Cenarius y dejaron entrar la Pesadilla Esmeralda en las Cuevas de los Lamentos.",
    ["These were theirs."] = "Estas piezas eran suyas.",
    ["The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain."] = "El Señor del Fuego, uno de los cuatro señores elementales, atado al Plano Elemental hasta que los enanos Hierro Negro lo invocaron bajo la Montaña Roca Negra.",
    ["The summoning cracked the mountain open and made the Molten Core."] = "La invocación abrió la montaña y creó el Núcleo de Magma.",
    ["The Guardian's staff, broken and scattered."] = "El bastón del Guardián, roto y disperso.",
    ["Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it."] = "Reconstruirlo significa reunir cuarenta astillas en Naxxramas, la base en Kel'Thuzad, y llevarlo a la ruina de Karazhan, donde Medivh lo sostuvo antaño.",
    ["The Scarlet Crusade's chief scholar, who guards the Monastery library and its collection rather more aggressively than a librarian should."] = "El principal erudito de la Cruzada Escarlata, que guarda la biblioteca del Monasterio y su colección con más ahínco del que debería un bibliotecario.",
    ["The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub."] = "El Cazador de Almas, un dios de sangre que los sacerdotes Atal'ai invocaron en Zul'Gurub.",
    ["He feeds on the blood of his own worshippers, which is the part they had not planned for."] = "Se alimenta de la sangre de sus propios adoradores, que es la parte que no habían planeado.",
    ["The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto."] = "La milicia de Stromgarde ha puesto precio a las cabezas de lord Cresta de Halcón y de su guardaespaldas Otto.",
    ["Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."] = "Falconcrest dirige los esfuerzos del Sindicato en las Tierras Altas de Arathi, y su muerte los desbarataría gravemente.",
    ["The Whirlwind Axe comes from an elemental trial a warrior has to complete alone."] = "El Hacha espirálica viene de una prueba elemental que un guerrero tiene que completar solo.",
    ["Three weapons come from the same chain and you keep only one."] = "Tres armas salen de la misma cadena y solo te quedas una.",
    ["The black dragonflight's overseer in Lower Blackrock Spire, keeping the orcs there in line on Nefarian's behalf."] = "El supervisor del vuelo negro en la Cumbre de Roca Negra inferior, que mantiene a raya a los orcos de allí en nombre de Nefarian.",
    ["The blade the Silver Hand carried against the Scourge, and the one Tirion Fordring's order was built around."] = "La hoja que la Mano de Plata llevó contra la Plaga, y en torno a la cual se alzó la orden de Tirion Fordring.",
    ["Corrupted when Renault Mograine used it on his own father, Alexandros, in the Scarlet Monastery."] = "Corrompida cuando Renault Mograine la usó contra su propio padre, Alexandros, en el Monasterio Escarlata.",
    ["The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."] = "El último de los tres dracos de Nefarian, el que simplemente se enfurece más a medida que avanza el combate.",
    ["The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."] = "La mejor soldado del imperio qiraji, que combate con su guardia de honor y se niega a separarse de ellos.",
    ["The third of the qiraji council, who charges the moment the fight begins and does not stop."] = "El tercero del consejo qiraji, que carga en cuanto empieza el combate y no se detiene.",
    ["Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength."] = "Emperador gemelo de los qiraji, el que heredó el don de C'Thun para la magia en vez de la fuerza de su hermano.",
    ["Neither twin can be killed far from the other."] = "Ninguno de los gemelos puede morir lejos del otro.",
    ["Twin emperor of the qiraji, and the stronger arm of the pair."] = "Emperador gemelo de los qiraji, y el brazo más fuerte de la pareja.",
    ["Two extra attacks on a proc, on a fast axe."] = "Dos ataques extra al activarse, en un hacha rápida.",
    ["Warriors farmed Dire Maul for this one item and nothing else."] = "Los guerreros farmeaban La Masacre solo por este objeto y por nada más.",
    ["Wanted: Arnak Grimtotem Arnak the outcast is wanted for the heinous crimes of murder and kidnapping."] = "Se busca: Arnak Tótem Siniestro. Arnak el paria es buscado por los crímenes atroces de asesinato y secuestro.",
    ["Handsome rewards will be given to those brave enough to bring this criminal to justice."] = "Habrá buenas recompensas para quien tenga el valor de llevar a este criminal ante la justicia.",
    ["Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn."] = "Se busca: Hogger. Un gnoll enorme, Hogger, merodea por los bosques del suroeste de Elwynn.",
    ["Wanted: Maggot Eye!"] = "¡Se busca: Ojo de gusano!",
    ["A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken."] = "Bestia inmunda incluso para ser un gnoll, Ojo de gusano ha sido condenado a muerte por sus crímenes contra los Renegados.",
    ["This despicable villain has been stealing corpses for use by the Lich King's army."] = "Este vil despreciable ha estado robando cadáveres para el ejército del Rey Exánime.",
    ["We mages do more than just waggle our fingers and make pretty sparks!"] = "¡Los magos hacemos más que menear los dedos y soltar chispas bonitas!",
    ["We control magic, the base fabric of our world!"] = "¡Controlamos la magia, el tejido mismo de nuestro mundo!",
    ["And that takes great care, and resolve."] = "Y eso exige mucho cuidado y resolución.",
    ["What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."] = "Lo que queda de un dragón verde que entró en el Templo Sumergido tras la Pesadilla y no salió siendo él mismo.",
    ["You have earned reverence among the Guard."] = "Te has ganado la reverencia de la Guardia.",
    ["Present your insignia!"] = "¡Presenta tu insignia!",
    ["You have earned the Eye of Command."] = "Te has ganado el Ojo de Mando.",
    ["Present your insignia, Commander."] = "Presenta tu insignia, comandante.",
    ["For this, you have earned a rank of honor among the Stormpike."] = "Por ello te has ganado un rango de honor entre los de Pico Tormenta.",
    ["Your radiate command and power, shaman."] = "Irradias mando y poder, chamán.",
    ["Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name."] = "Exaltado a los ojos de los Lobos Gélidos: el enemigo se encoge al oír tu nombre.",
    ["Your time has come again."] = "Tu hora ha vuelto.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature."] = "Te has ganado un nuevo rango y, con él, una nueva insignia que marca ese ascenso.",
    ["A burst of energy fills the caster, increasing his damage by 10 and armor by 150 for 15 sec."] = "Una descarga de energía llena al taumaturgo, aumentando su daño en 10 y su armadura en 150 durante 15 s.",
    ["Attack all nearby enemies, dealing weapon damage plus 5 every 3 sec for 9 sec, and reducing your own movement speed by 80%."] = "Ataca a todos los enemigos cercanos, infligiendo el daño del arma más 5 cada 3 s durante 9 s, y reduce tu velocidad de movimiento un 80%.",
    ["Blast the target with the fires of a forge, inflicting 51 Fire damage."] = "Golpea al objetivo con los fuegos de una forja e inflige 51 p. de daño de Fuego.",
    ["Blasts enemies in front of you with the power of wind, fire, all that kind of thing!"] = "¡Golpea a los enemigos frente a ti con el poder del viento, del fuego y todo eso!",
    ["Blasts nearby enemies with thunder increasing the time between their attacks by 11% for 10 sec and doing 42 Nature damage to them. � Will affect up to 4 targets."] = "Golpea a los enemigos cercanos con el trueno, aumentando el tiempo entre sus ataques un 11% durante 10 s e infligiéndoles 42 p. de daño de Naturaleza. Afecta hasta a 4 objetivos.",
    ["Blunderflame the target for 1 to 111 Fire damage."] = "Malflama al objetivo e inflige de 1 a 111 p. de daño de Fuego.",
    ["Burns the enemy for 200 damage over 30 sec."] = "Quema al enemigo e inflige 200 p. de daño durante 30 s.",
    ["Burns the target for 33 Fire damage every 3 sec for 15 sec."] = "Quema al objetivo e inflige 33 p. de daño de Fuego cada 3 s durante 15 s.",
    ["Concuss the target, slowing movement speed by 20% for 6 sec."] = "Conmociona al objetivo y reduce su velocidad de movimiento un 20% durante 6 s.",
    ["Cremate the target for 56 Fire damage."] = "Incinera al objetivo e inflige 56 p. de daño de Fuego.",
    ["Damage caused by the target is reduced by 5 for 2 min."] = "El daño que causa el objetivo se reduce en 5 durante 2 min.",
    ["Deal 294 Physical damage and stun for1.5 sec."] = "Inflige 294 p. de daño físico y aturde durante 1,5 s.",
    ["Trolls take 2 times as much damage and stun duration."] = "Los trols sufren 2 veces más daño y 2 veces más duración del aturdimiento.",
    ["Deal 84 Nature damage, increased by 2% per stack of Static Electricity."] = "Inflige 84 p. de daño de Naturaleza, aumentado un 2% por cada acumulación de Electricidad estática.",
    ["Deals 14 Nature damage every 3 sec to any enemy in an 8 yard radius around the caster for 12 sec."] = "Inflige 14 p. de daño de Naturaleza cada 3 s a cualquier enemigo en un radio de 8 m alrededor del taumaturgo durante 12 s.",
    ["Decrease the armor of the target by 100 for 20 sec. � While affected, the target cannot stealth or turn invisible."] = "Reduce la armadura del objetivo en 100 durante 20 s. Mientras dura el efecto, el objetivo no puede entrar en sigilo ni volverse invisible.",
    ["Deals 50% increased damage to targets below 25% health."] = "Inflige un 50% más de daño a objetivos por debajo del 25% de salud.",
    ["Discipline the target, dealing 91 Physical damage."] = "Disciplina al objetivo e inflige 91 p. de daño físico.",
    ["Canines and Hyenas are Stunned and sit for 3 sec."] = "Los cánidos y las hienas quedan aturdidos y se sientan durante 3 s.",
    ["Diseases a target for 100 Nature damage and an additional 360 damage over 1 min."] = "Enferma a un objetivo e inflige 100 p. de daño de Naturaleza y 360 p. de daño adicionales durante 1 min.",
    ["Disorients the target, causing it to wander aimlessly for up to 3 sec."] = "Desorienta al objetivo, que vaga sin rumbo hasta 3 s.",
    ["Dispels a magic effect on the current foe."] = "Disipa un efecto mágico del enemigo actual.",
    ["Enemy is inflicted with the Bleakwood Curse that reduces their magic resistances by 25. � Can be applied up to 3 times."] = "El enemigo sufre la Maldición de Bosque Umbrío, que reduce sus resistencias mágicas en 25. Se puede aplicar hasta 3 veces.",
    ["Fires a Shadow Shot at the target for 21 to 31 Shadow damage."] = "Dispara un Tiro de las Sombras al objetivo e inflige de 21 a 31 p. de daño de Sombras.",
    ["Heal yourself for 270 to 450 and increase your Strength by 120 for 30 sec."] = "Te sana de 270 a 450 p. y aumenta tu fuerza en 120 durante 30 s.",
    ["Heals the wielder for 182 damage over 14 sec."] = "Sana al portador 182 p. durante 14 s.",
    ["Hurl spikes at the target, dealing 45 Physical damage and jumping to 1 additional nearby enemy."] = "Lanza púas al objetivo, inflige 45 p. de daño físico y salta a 1 enemigo cercano adicional.",
    ["Each jump reduces the damage by 50%."] = "Cada salto reduce el daño un 50%.",
    ["Ignite the target in the flames of the Great Forge, dealing 39 to 59 Holyfire damage."] = "Enciende al objetivo en las llamas de la Gran Forja e inflige de 39 a 59 p. de daño de Fuego sagrado.",
    ["Increases your chance to Parry attacks by 2% for 9 sec."] = "Aumenta tu probabilidad de parar ataques un 2% durante 9 s.",
    ["Inflict 42 Fire and 14 Frost damage, slow the target by 50% for 5 sec, reduce armor by 50, and inflict 7 Nature damage every 3 sec for 12 sec."] = "Inflige 42 p. de daño de Fuego y 14 de Escarcha, ralentiza al objetivo un 50% durante 5 s, reduce la armadura en 50 e inflige 7 p. de daño de Naturaleza cada 3 s durante 12 s.",
    ["Knocks down all nearby enemies for 3 sec."] = "Derriba a todos los enemigos cercanos durante 3 s.",
    ["Launch a magic severing bolt at the target, dealing 36 Physical damage and interrupting the spell being cast for 5 sec."] = "Lanza un proyectil que corta la magia al objetivo, inflige 36 p. de daño físico e interrumpe el hechizo que lanza durante 5 s.",
    ["Lowers the Attack Power of the target by 40 for 1 min."] = "Reduce el poder de ataque del objetivo en 40 durante 1 min.",
    ["Protects the caster with a holy shield."] = "Protege al taumaturgo con un escudo sagrado.",
    ["Pummel the target for 25 damage and interrupt the spell being cast for 5 sec."] = "Zurra al objetivo, inflige 25 p. de daño e interrumpe el hechizo que lanza durante 5 s.",
    ["Punctures target's armor, lowering it by 100."] = "Perfora la armadura del objetivo y la reduce en 100.",
    ["Reduce your threat to the current target making them less likely to attack you."] = "Reduce tu amenaza hacia el objetivo actual, y así es menos probable que te ataque.",
    ["Reduces an enemy's armor by 165. � Stacks up to 3 times."] = "Reduce la armadura de un enemigo en 165. Se acumula hasta 3 veces.",
    ["Reduces targets armor by 300 for 20 sec."] = "Reduce la armadura del objetivo en 300 durante 20 s.",
    ["Sear certain enchanted targets with blazing light causing them to take additional damage from Holy attacks and spells."] = "Abrasa a ciertos objetivos encantados con luz ardiente, y así sufren daño adicional de los ataques y hechizos Sagrados.",
    ["Sear the target with a vortex of blazing wind, dealing 39 to 59 Holystorm damage."] = "Abrasa al objetivo con un vórtice de viento ardiente e inflige de 39 a 59 p. de daño de Tormenta sagrada.",
    ["Sear your target's flesh, dealing 67 to 101 Fire damage."] = "Abrasa la carne de tu objetivo e inflige de 67 a 101 p. de daño de Fuego.",
    ["Slice the target's ankle, slowing movement speed by 30% for 6 sec."] = "Corta el tobillo del objetivo y reduce su velocidad de movimiento un 30% durante 6 s.",
    ["Slices the enemy for 72 to 96 Nature damage."] = "Corta al enemigo e inflige de 72 a 96 p. de daño de Naturaleza.",
    ["Slows the target's movement by 50% for 10 sec."] = "Ralentiza el movimiento del objetivo un 50% durante 10 s.",
    ["Slows the target's movement speed by 30% and increases the time between their attacks by 25% for 5 sec."] = "Reduce la velocidad de movimiento del objetivo un 30% y aumenta el tiempo entre sus ataques un 25% durante 5 s.",
    ["Smash the target for 85 damage."] = "Machaca al objetivo e inflige 85 p. de daño.",
    ["Smite your target with the power of the holy spring, inflicting 56 Holy damage."] = "Castiga a tu objetivo con el poder del manantial sagrado e inflige 56 p. de daño Sagrado.",
    ["Smites an enemy for 30 Holy damage."] = "Castiga a un enemigo e inflige 30 p. de daño Sagrado.",
    ["Spell damage taken by target increased by 15% for 5 sec."] = "El daño de hechizos que sufre el objetivo aumenta un 15% durante 5 s.",
    ["Strike the target with a Flaming Shell for 32 to 46 Fire damage."] = "Golpea al objetivo con una Carcasa llameante e inflige de 32 a 46 p. de daño de Fuego.",
    ["Strike the target with a Flaming Shell, inflicting 7 Fire damage every 3 sec for 9 sec."] = "Golpea al objetivo con una Carcasa llameante e inflige 7 p. de daño de Fuego cada 3 s durante 9 s.",
    ["Strike your target with Keeper's Sting for 23 to 33 Nature damage."] = "Golpea a tu objetivo con el Aguijón del guardián e inflige de 23 a 33 p. de daño de Naturaleza.",
    ["Tenderize the target, increasing physical damage taken by 1 for 1 min."] = "Ablanda al objetivo y aumenta en 1 el daño físico que sufre durante 1 min.",
    ["Venom Shot the target for 23 to 33 Nature damage."] = "Disparo venenoso al objetivo e inflige de 23 a 33 p. de daño de Naturaleza.",
    ["Naga are Stunned for 2 sec."] = "Los naga quedan aturdidos durante 2 s.",
    ["Your attacks have a high chance to poison the target for 8 Nature damage every 3 sec for 9 sec."] = "Tus ataques tienen una probabilidad alta de envenenar al objetivo e infligirle 8 p. de daño de Naturaleza cada 3 s durante 9 s.",
    ["Causes Wrath to have a 50% chance to restore 35 Mana."] = "Hace que Cólera tenga un 50% de probabilidad de restaurar 35 p. de maná.",
    ["Chance on harmful spell cast to reduce target's attack power by 60 for 30 sec."] = "Probabilidad al lanzar un hechizo dañino de reducir el poder de ataque del objetivo en 60 durante 30 s.",
    ["Chance on harmful spell cast to summon a Zombie Troll of Zum'rah for 20 sec."] = "Probabilidad al lanzar un hechizo dañino de invocar un trol zombi de Zum'rah durante 20 s.",
    ["Chance on hit to blast the target for 25 to 31 Fire damage."] = "Probabilidad al acertar de golpear al objetivo e infligir de 25 a 31 p. de daño de Fuego.",
    ["Chance on hit to deal 69 to 81 Arcane damage."] = "Probabilidad al acertar de infligir de 69 a 81 p. de daño Arcano.",
    ["Chance on hit to grant nearby party members 4% increased critical strike chance."] = "Probabilidad al acertar de otorgar a los miembros del grupo cercanos un 4% más de probabilidad de golpe crítico.",
    ["Chance on hit to reduce the mana cost of your next spell cast within 10 sec by 24."] = "Probabilidad al acertar de reducir en 24 el coste de maná de tu próximo hechizo lanzado en 10 s.",
    ["Chance on hit to restore 32 mana."] = "Probabilidad al acertar de restaurar 32 p. de maná.",
    ["Restores 3 times as much if attacking an Earth Elemental, Golem, or Titan-forged enemy."] = "Restaura 3 veces más si atacas a un elemental de tierra, un gólem o un enemigo forjado por los titanes.",
    ["Chance to strike your ranged target with a Shadowbolt for 13 to 19 Shadow damage."] = "Probabilidad de golpear a tu objetivo a distancia con una Descarga de las Sombras e infligir de 13 a 19 p. de daño de Sombras.",
    ["Harmful spell casts have a chance to steal 112 life from the target enemy over 8 sec."] = "Los hechizos dañinos tienen una probabilidad de robar 112 p. de vida al enemigo objetivo durante 8 s.",
    ["Melee attacks deal 98 Fire additional damage against Frozen targets."] = "Los ataques cuerpo a cuerpo infligen 98 p. de daño de Fuego adicionales contra objetivos congelados.",
    ["Reduces all damage taken and chance to be critically hit by 5% in Warsong Gulch."] = "Reduce todo el daño recibido y la probabilidad de recibir un golpe crítico un 5% en la Garganta Grito de Guerra.",
    ["When damaged, has a chance to grant you 1080 armor for 12 sec."] = "Al recibir daño, tiene una probabilidad de otorgarte 1080 p. de armadura durante 12 s.",
    ["When damaged, has a chance to reduce threat level on all enemies by a small amount for 10 sec."] = "Al recibir daño, tiene una probabilidad de reducir un poco tu amenaza hacia todos los enemigos durante 10 s.",
    ["When struck in combat has a 3% chance to heal you for 60 to 100."] = "Al ser golpeado en combate tiene un 3% de probabilidad de sanarte de 60 a 100 p.",
    ["When struck in combat has a 5% chance to make you invulnerable to melee damage for 3 sec."] = "Al ser golpeado en combate tiene un 5% de probabilidad de volverte inmune al daño cuerpo a cuerpo durante 3 s.",
    ["This effect can only occur once every 10 sec."] = "Este efecto solo puede ocurrir una vez cada 10 s.",
    ["While in combat, your healing spells have a chance to grant an ally 300 armor for 10 sec."] = "En combate, tus hechizos de sanación tienen una probabilidad de otorgar a un aliado 300 p. de armadura durante 10 s.",
    ["Your Frostbolt spells have a 6% chance to restore 50 mana when cast."] = "Tus Descargas de Escarcha tienen un 6% de probabilidad de restaurar 50 p. de maná al lanzarlas.",
    ["Your Lacerate hits have a 10% chance to reset the cooldown on Mangle (Bear)."] = "Tus golpes de Lacerar tienen un 10% de probabilidad de reiniciar el tiempo de reutilización de Destrozar (oso).",
    ["Your healing spells have a 5% chance to remove 1 Poison effect from the target."] = "Tus hechizos de sanación tienen un 5% de probabilidad de eliminar 1 efecto de veneno del objetivo.",
    ["Absorbs 600 magical damage. � Lasts 2 min."] = "Absorbe 600 p. de daño mágico. Dura 2 min.",
    ["Allows you to look far into the distance."] = "Te permite ver muy lejos.",
    ["Attach a lure to your equipped fishing pole, increasing Fishing by 25 for 10 min."] = "Acopla un cebo a la caña de pescar equipada y aumenta Pesca en 25 durante 10 min.",
    ["Attempts to cure 1 poison effect on the target, and 1 more poison effect every 2 seconds for 8 sec."] = "Intenta curar 1 efecto de veneno del objetivo, y 1 efecto de veneno más cada 2 segundos durante 8 s.",
    ["Balance the Powers of the Moon, Emerald Dream, and Wild to learn a new ability."] = "Equilibra los poderes de la Luna, el Sueño Esmeralda y lo Salvaje para aprender una facultad nueva.",
    ["Channels a bolt of lightning and hurls it towards all enemies in front of the caster causing 189 to 209 Nature damage."] = "Canaliza un rayo y lo lanza hacia todos los enemigos frente al taumaturgo, infligiendo de 189 a 209 p. de daño de Naturaleza.",
    ["The caster is then surrounded by a barrier of electricit"] = "El taumaturgo queda entonces rodeado por una barrera de electricidad.",
    ["Chop nearby Humanoid or Undead corpse in two, restoring 150 Health, 150 Mana, and 15 Rage."] = "Parte en dos un cadáver cercano de humanoide o no-muerto y restaura 150 p. de salud, 150 p. de maná y 15 p. de ira.",
    ["Combines Jang'thraze and Sang'thraze to form the mighty sword, Sul'thraze."] = "Combina Jang'thraze y Sang'thraze para formar la poderosa espada Sul'thraze.",
    ["Conjures food to eat."] = "Conjura comida.",
    ["Creates a portal, teleporting group members that use it to Karazhan."] = "Crea un portal que teletransporta a Karazhan a los miembros del grupo que lo usan.",
    ["Deal 607 Physical damage split between up to 4 nearby enemies."] = "Inflige 607 p. de daño físico repartidos entre un máximo de 4 enemigos cercanos.",
    ["Deals 25 Fire damage every 5 sec to all nearby enemies for 15 sec."] = "Inflige 25 p. de daño de Fuego cada 5 s a todos los enemigos cercanos durante 15 s.",
    ["Deals 504 Fire damage over 12 sec."] = "Inflige 504 p. de daño de Fuego durante 12 s.",
    ["Demons and Beasts are Rooted in place for 6 sec."] = "Los demonios y las bestias quedan enraizados durante 6 s.",
    ["Deals 75 Fire damage every 1 sec for 5 sec to all enemies in front of you."] = "Inflige 75 p. de daño de Fuego cada 1 s durante 5 s a todos los enemigos frente a ti.",
    ["Gets you quite drunk too!"] = "¡Y también te emborracha bastante!",
    ["Decrease the armor of target by 50 for 1 min."] = "Reduce la armadura del objetivo en 50 durante 1 min.",
    ["Dig up a grave."] = "Desentierra una tumba.",
    ["Usable at Raven Hill Cemetery and Scarlet Monastery Graveyard."] = "Se puede usar en el Cementerio del Cerro del Cuervo y en el cementerio del Monasterio Escarlata.",
    ["Escape all immobilizing effects."] = "Te liberas de todos los efectos de inmovilización.",
    ["Fear all Demons within 15 yds for 6 sec."] = "Aterroriza a todos los demonios a menos de 15 m durante 6 s.",
    ["Gain the ability to walk on water for 5 min.Attacking or taking damage will cancel this effect."] = "Te permite caminar sobre el agua durante 5 min. Atacar o recibir daño cancela este efecto.",
    ["Heal your pet for 450 to 750."] = "Sana a tu mascota de 450 a 750 p.",
    ["Increase Rage by 30."] = "Aumenta la ira en 30.",
    ["Increase experience gained from slaying Undead by 10% for 5 min."] = "Aumenta un 10% la experiencia obtenida al matar no-muertos durante 5 min.",
    ["Increase your run speed by 60% for 10 sec, but deals 100 to 500 damage and drains 100 to 500 mana every 2 seconds."] = "Aumenta tu velocidad de carrera un 60% durante 10 s, pero inflige de 100 a 500 p. de daño y drena de 100 a 500 p. de maná cada 2 segundos.",
    ["This effect is doubled in Volcanic areas."] = "Este efecto se duplica en zonas volcánicas.",
    ["Increases Fire resistance by 33 and absorbs 465 Fire damage. � Lasts 15 sec."] = "Aumenta la resistencia al Fuego en 33 y absorbe 465 p. de daño de Fuego. Dura 15 s.",
    ["Increases all Resistances by 10 and grants Immunity to Fear for 30 sec."] = "Aumenta todas las resistencias en 10 y otorga inmunidad al miedo durante 30 s.",
    ["Increases damage and healing done by magical spells and effects by up to 130 for 20 sec."] = "Aumenta el daño y la sanación de los hechizos y efectos mágicos hasta 130 durante 20 s.",
    ["Increases healing done by the next 5 spells by up to 450 for 30 sec."] = "Aumenta la sanación de los 5 próximos hechizos hasta 450 durante 30 s.",
    ["Increases your Block chance by 8% for 15 sec."] = "Aumenta tu probabilidad de bloqueo un 8% durante 15 s.",
    ["This effect is doubled in Strongholds and Cities."] = "Este efecto se duplica en bastiones y ciudades.",
    ["Increases your attack speed by 50% for 30 sec."] = "Aumenta tu velocidad de ataque un 50% durante 30 s.",
    ["Increases your chance to Dodge by 3% for 20 sec."] = "Aumenta tu probabilidad de esquivar un 3% durante 20 s.",
    ["Increases your critical strike chance with all spells and attacks by 5% for 20 sec or until you deal a non-periodic critical effect."] = "Aumenta tu probabilidad de golpe crítico con todos los hechizos y ataques un 5% durante 20 s, o hasta que inflijas un efecto crítico no periódico.",
    ["Increases your effective stealth detection level by 3 for 10 sec, then reduces your effective stealth detection level by 6 for 20 sec."] = "Aumenta tu nivel efectivo de detección del sigilo en 3 durante 10 s y luego lo reduce en 6 durante 20 s.",
    ["Increases your melee and ranged attack power by 280. � Effect lasts for 20 sec."] = "Aumenta tu poder de ataque cuerpo a cuerpo y a distancia en 280. El efecto dura 20 s.",
    ["Lets you walk on water for 1 min."] = "Te permite caminar sobre el agua durante 1 min.",
    ["Marks a target for delivery."] = "Marca un objetivo para una entrega.",
    ["After landing 6 to 8 spells or attacks, deal 467 Fire damage."] = "Tras acertar de 6 a 8 hechizos o ataques, inflige 467 p. de daño de Fuego.",
    ["Number of spells or attacks is halved in Snowy areas."] = "El número de hechizos o ataques se reduce a la mitad en zonas nevadas.",
    ["Melee attacks deal an additional 7 Fire damage for 30 sec."] = "Los ataques cuerpo a cuerpo infligen 7 p. de daño de Fuego adicionales durante 30 s.",
    ["Page Everlook Emergency Services for a Parachute-Priest that will assist in healing allies for 15 sec."] = "Llama a los servicios de urgencia de Vista Eterna para un sacerdote paracaidista que ayuda a sanar a los aliados durante 15 s.",
    ["Perform a Propellerstorm, reducing your fall speed for 15 sec and dealing 100% weapon damage to nearby enemies when you land."] = "Ejecuta una tormenta de hélices, reduce tu velocidad de caída durante 15 s e inflige un 100% del daño del arma a los enemigos cercanos al aterrizar.",
    ["Purifies the friendly target, removing 1 disease effect and 1 poison effect."] = "Purifica al objetivo amigo y elimina 1 efecto de enfermedad y 1 efecto de veneno.",
    ["Raise the severed head of Roogug, Horrifying and Silencing all Swine within 15 yds for 5 sec."] = "Alza la cabeza cortada de Roogug, que aterroriza y silencia a todos los cerdos a menos de 15 m durante 5 s.",
    ["Reduces your fall speed for 10 sec."] = "Reduce tu velocidad de caída durante 10 s.",
    ["Removes existing Immobilizing effects and makes you immune to Immobilizing effects for 5 sec."] = "Elimina los efectos de inmovilización presentes y te vuelve inmune a ellos durante 5 s.",
    ["Restores 1293 mana over 27 sec. � Must remain seated while drinking."] = "Restaura 1293 p. de maná durante 27 s. Debes permanecer sentado mientras bebes.",
    ["Can only be used at 10% health."] = "Solo se puede usar al 10% de salud.",
    ["Slice open and gather from a target Copper, Tin, Silver, or Iron Vein (does not require Mining)."] = "Abre y recoge de un filón de cobre, estaño, plata o hierro seleccionado (no requiere Minería).",
    ["Slows nearby enemies by 50% for 10 sec, increased to 80% in Desert areas."] = "Ralentiza a los enemigos cercanos un 50% durante 10 s, y un 80% en zonas desérticas.",
    ["Stuns target Undead for 6 sec."] = "Aturde al no-muerto objetivo durante 6 s.",
    ["Stuns target Worgen for 4 sec."] = "Aturde al huargen objetivo durante 4 s.",
    ["Summons a tracking hound that will protect you for 3 min."] = "Invoca un sabueso rastreador que te protege durante 3 min.",
    ["Weakens the servants of Razelikh the Defiler."] = "Debilita a los sirvientes de Razelikh el Envilecido.",
    ["Must be within close proximity of the target to activate."] = "Debes estar muy cerca del objetivo para activarlo.",
    ["As my understanding of Arugal's magic grows so does my disdain for the hapless fool."] = "Cuanto más entiendo la magia de Arugal, más desprecio a ese pobre necio.",
    ["I am close to completing my research on his so called remedy."] = "Estoy a punto de terminar mi investigación sobre su supuesto remedio.",
    ["Edwin VanCleef must be assassinated."] = "Hay que asesinar a Edwin VanCleef.",
    ["While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."] = "Aunque me apena condenar a un hombre a muerte, es por el bien del pueblo de los Páramos de Poniente que VanCleef quede fuera de combate de una vez por todas.",
    ["Here is the final challenge that I will put forth."] = "Este es el último desafío que te planteo.",
    ["We've been tracking an elusive tiger for weeks."] = "Llevamos semanas siguiendo a un tigre escurridizo.",
    ["I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done."] = "Saco mi fuerza, mi voluntad de seguir viviendo y respirando, del odio absoluto que siento por la Plaga y por todo lo que ha hecho.",
    ["I must warn you, this matter must stay between us."] = "Debo advertirte: este asunto tiene que quedar entre nosotros.",
    ["The satyr are enough of an embarrassment to us already, and this one is much too close to home."] = "Los sátiros ya son una vergüenza suficiente para nosotros, y este está demasiado cerca de casa.",
    ["Prospector Whelgar now holds the original fossil at his site in the Wetlands."] = "El prospector Whelgar tiene ahora el fósil original en su excavación de Los Humedales.",
    ["When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil."] = "Cuando descubrí la Piedra de Relu, creí que era la clave del misterio del fósil.",
    ["So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus?"] = "¿Así que el prospector quiere enviar el fósil misterioso a la Liga de Expedicionarios en Darnassus?",
    ["I don't feel right leaving Darkshore without him."] = "No me parece bien irme de Costa Oscura sin él.",
    ["Strength has left me."] = "Las fuerzas me han abandonado.",
    ["Your help is needed!"] = "¡Se necesita tu ayuda!",
    ["Long ago this site was a great temple of Elune."] = "Hace mucho, este lugar era un gran templo de Elune.",
    ["But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."] = "Pero la desgracia lo llevó a la ruina cuando la corrupción de un Dios Antiguo manó de las profundidades y mancilló el Pozo de la Luna sagrado.",
    ["This Twilight's Hammer follower cannot be allowed to complete his plan."] = "No se puede permitir que este seguidor del Martillo Crepuscular complete su plan.",
    ["The Twilight's Hammer do not understand the spirits of nature."] = "El Martillo Crepuscular no entiende a los espíritus de la naturaleza.",
    ["They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."] = "Creen en los Dioses Antiguos, criaturas de caos y destrucción derrotadas hace mucho.",
    ["This shard holds great secrets; it is the pure essence of the Emerald Dream."] = "Esta esquirla guarda grandes secretos; es la esencia pura del Sueño Esmeralda.",
    ["However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare."] = "Sin embargo, lo que veo en esta esquirla no es un sueño; a una visión así se la llamaría pesadilla.",
    ["We believe they are hiding out in the Dagger Hills, plotting their next move."] = "Creemos que se esconden en las Colinas Afiladas, tramando su siguiente paso.",
    ["Slay the wretches in the name of The People's Militia."] = "Mata a esos miserables en nombre de las Milicias del Pueblo.",
    ["While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost."] = "Mientras viajaba para reunirme con Whelgar, unos raptores me atacaron y la reliquia se perdió.",
    ["(be aware that some vendors sell items at random)"] = "(ten en cuenta que algunos vendedores venden objetos al azar)",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil."] = "Comprado al corredor de runas en Ventormenta, Forjaz, Darnassus, el Bosque de Elwynn, Dun Morogh y Teldrassil.",
    ["Bought from Rune Broker in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Comprado al corredor de runas en Orgrimmar, Cima del Trueno, Entrañas, Durotar, Mulgore y los Claros de Tirisfal.",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil, and in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Comprado al corredor de runas en Ventormenta, Forjaz, Darnassus, el Bosque de Elwynn, Dun Morogh y Teldrassil, y en Orgrimmar, Cima del Trueno, Entrañas, Durotar, Mulgore y los Claros de Tirisfal.",
    ["Found in a container."] = "Se encuentra en un contenedor.",
    ["The belt is crafted afterwards."] = "El cinturón se fabrica después.",
    ["You have 5 hours to complete this task."] = "Tienes 5 horas para completar esta tarea.",
    ["Collect 4 pieces for the heal and mana, and all 5 for Dream Venom."] = "Reúne 4 piezas para la sanación y el maná, y las 5 para Veneno de ensueño.",
    ["Collect 4 pieces for the heal and mana."] = "Reúne 4 piezas para la sanación y el maná.",
    ["Provided item:."] = "Objeto proporcionado:",
    ["The Blacksmithing plans are a drop."] = "Los planos de herrería son un botín.",
    ["The creature is not named yet."] = "La criatura todavía no tiene nombre.",
}) do sentences[k] = v end
